width:52px;height:52px;background:var(--accent);border-radius:16px;border:none;cursor:pointer;z-index:99;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 20px rgba(34,196,122,.4);color:#fff}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:20px}.stat-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px;position:relative;overflow:hidden}.stat-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:var(--card-accent,var(--accent))}.stat-label{color:var(--text3);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px}.stat-value{font-size:26px;font-weight:800;line-height:1;margin-bottom:4px}.stat-sub{color:var(--text2);font-size:11px}.search-bar{display:flex;align-items:center;gap:10px;margin-bottom:14px;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:0 14px}.search-bar input{flex:1;background:none;border:none;outline:none;color:var(--text);font-size:14px;padding:12px 0;font-family:inherit}.search-bar input::placeholder{color:var(--text3)}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.section-title{font-size:15px;font-weight:700}.record-list{display:flex;flex-direction:column;gap:10px}.record-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px 16px}.record-card-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px}.record-name{font-size:15px;font-weight:700;color:var(--text)}.record-id{font-size:11px;color:var(--text3);font-weight:600}.record-meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.meta-chip{background:rgba(255,255,255,.04);border:1px solid var(--border);border-radius:6px;padding:3px 8px;font-size:11px;color:var(--text2)}.record-actions{display:flex;gap:8px;margin-top:12px;padding-top:10px;border-top:1px solid var(--border)}.btn-sm{flex:1;padding:8px;border-radius:9px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;border:1px solid;display:flex;align-items:center;justify-content:center;gap:5px}.btn-edit-sm{background:rgba(61,155,232,.1);border-color:rgba(61,155,232,.3);color:var(--accent2)}.btn-del-sm{background:rgba(232,80,80,.1);border-color:rgba(232,80,80,.3);color:var(--danger)}.badge{font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;letter-spacing:.04em;white-space:nowrap;display:inline-flex}.sheet-overlay{position:fixed;inset:0;background:rgba(0,10,20,.8);backdrop-filter:blur(6px);z-index:200;display:none;align-items:flex-end;justify-content:center}.sheet-overlay.open{display:flex}.sheet{background:var(--surface2);border:1px solid var(--border);border-radius:20px 20px 0 0;width:100%;max-height:90vh;overflow-y:auto;padding-bottom:20px;animation:slideUp .3s cubic-bezier(.34,1.56,.64,1)}@keyframes slideUp{from{transform:translateY(100%)}to{transform:translateY(0)}}.sheet-handle{width:36px;height:4px;background:var(--border);border-radius:2px;margin:12px auto 16px}.sheet-title{font-size:17px;font-weight:800;color:var(--text);padding:0 20px 16px;border-bottom:1px solid var(--border)}.sheet-body{padding:20px}.field{margin-bottom:16px}.field label{display:block;color:var(--text2);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;margin-bottom:7px}.field input,.field select{width:100%;padding:13px 14px;background:var(--bg);border:1px solid var(--border);border-radius:11px;color:var(--text);font-size:15px;outline:none;font-family:inherit;-webkit-appearance:none}.field input:focus,.field select:focus{border-color:var(--accent)}.form-2col{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.sheet-footer{display:flex;gap:10px;padding:0 20px;margin-top:4px}.btn-primary{flex:1;padding:14px;background:var(--accent);border:none;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:inherit}.btn-secondary{padding:14px 20px;background:var(--surface);border:1px solid var(--border);border-radius:12px;color:var(--text2);font-size:15px;font-weight:600;cursor:pointer;font-family:inherit}.appt-card{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px 14px;display:flex;align-items:center;gap:12px;margin-bottom:8px}.appt-time-box{background:rgba(34,196,122,.1);border:1px solid rgba(34,196,122,.25);border-radius:9px;padding:6px 10px;text-align:center;flex-shrink:0}.appt-time{font-size:13px;font-weight:800;color:var(--accent)}.appt-name{font-size:14px;font-weight:700;color:var(--text)}.appt-doc{font-size:12px;color:var(--text2);margin-top:1px}.ward-scroll{display:flex;gap:10px;overflow-x:auto;padding-bottom:4px}.ward-scroll::-webkit-scrollbar{display:none}.ward-pill{flex-shrink:0;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:10px 14px;min-width:100px}.ward-pill-label{font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;margin-bottom:6px}.ward-pill-bar{background:#0f2236;border-radius:3px;height:4px;margin-bottom:5px}.ward-pill-fill{height:100%;border-radius:3px}.ward-pill-count{font-size:14px;font-weight:800;color:var(--text)}.bill-row{display:flex;gap:8px;margin-bottom:14px}.bill-mini{flex:1;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px}.bill-mini-label{font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;margin-bottom:4px}.bill-mini-val{font-size:16px;font-weight:800}.dash-section{margin-bottom:20px}.dash-section-title{font-size:12px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px}::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}select option{background:#0d1b2a}</style></head><body><div id="app"><div id="topbar"><div style="display:flex;align-items:center"><div class="topbar-logo"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg></div><span class="topbar-brand">MediCore</span></div><span class="topbar-time" id="clock"></span></div><div id="content"></div><button class="fab" id="fab" onclick="fabAction()" style="display:none"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button><nav id="bottom-nav"><button class="nav-item active" data-page="dashboard" onclick="navigate('dashboard')"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg><span class="nav-label">Home</span></button><button class="nav-item" data-page="patients" onclick="navigate('patients')"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg><span class="nav-label">Patients</span></button><button class="nav-item" data-page="doctors" onclick="navigate('doctors')"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="5"/><path d="M3 21a9 9 0 0 1 18 0"/></svg><span class="nav-label">Doctors</span></button><button class="nav-item" data-page="appointments" onclick="navigate('appointments')"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><span 