,Confirmed:["#0d3025","#22c47a"],Pending:["#2a2010","#d4a843"],Completed:["#1a2540","#6ea8d4"],Paid:["#0d3025","#22c47a"],Partial:["#2a2010","#d4a843"],Emergency:["#3d0d0d","#e85050"]};function badge(l){const[bg,fg]=BC[l]||["#1a2540","#6ea8d4"];return`<span class="badge" style="background:${bg};color:${fg}">${l}</span>`}let page="dashboard",searches={patients:"",doctors:"",appointments:"",billing:""};setInterval(()=>{document.getElementById("clock").textContent=new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})},1000);document.getElementById("clock").textContent=new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"});function navigate(p){page=p;document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===p));document.getElementById("fab").style.display=p==="dashboard"?"none":"flex";renderPage();document.getElementById("content").scrollTop=0}function openSheet(t,b){document.getElementById("sheet-title").textContent=t;document.getElementById("sheet-body").innerHTML=b;document.getElementById("sheet").classList.add("open")}function closeSheet(){document.getElementById("sheet").classList.remove("open")}const v=id=>(document.getElementById(id)||{value:""}).value,opt=(arr,cur)=>arr.map(x=>`<option${x===cur?" selected":""}>${x}</option>`).join("");function fabAction(){if(page==="patients")openPatientSheet(null);else if(page==="doctors")openDoctorSheet(null);else if(page==="appointments")openApptSheet(null);else if(page==="billing")openBillSheet(null)}function renderPage(){const el=document.getElementById("content");if(page==="dashboard")el.innerHTML=renderDash();else if(page==="patients")el.innerHTML=renderPatients();else if(page==="doctors")el.innerHTML=renderDoctors();else if(page==="appointments")el.innerHTML=renderAppts();else el.innerHTML=renderBilling()}function renderDash(){const admitted=patients.filter(p=>p.status==="Admitted").length,critical=patients.filter(p=>p.status==="Critical").length,onDuty=doctors.filter(d=>d.status==="On Duty").length,revenue=billing.reduce((s,b)=>s+b.paid,0),pending=billing.filter(b=>b.status!=="Paid").length,todayA=appointments.filter(a=>a.date==="2026-03-13");const wH=WARDS.map(w=>{const c=patients.filter(p=>p.ward===w&&p.status!=="Discharged").length,pct=(c/10)*100,col=pct>80?"#e85050":pct>50?"#d4a843":"#22c47a";return`<div class="ward-pill"><div class="ward-pill-label">${w}</div><div class="ward-pill-bar"><div class="ward-pill-fill" style="width:${pct}%;background:${col}"></div></div><div class="ward-pill-count">${c}<span style="color:var(--text3)">/10</span></div></div>`}).join("");const aH=todayA.length?todayA.map(a=>`<div class="appt-card"><div class="appt-time-box"><div class="appt-time">${a.time}</div></div><div><div class="appt-name">${a.patient}</div><div class="appt-doc">${a.doctor} · ${badge(a.status)}</div></div></div>`).join(""):`<div style="color:var(--text3);font-size:13px">No appointments today</div>`;const rH=[...patients].reverse().slice(0,3).map(p=>`<div class="appt-card"><div style="background:rgba(61,155,232,.1);border:1px solid rgba(61,155,232,.2);border-radius:9px;width:38px;height:38px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:14px;font-weight:800;color:var(--accent2)">${p.name[0]}</div><div style="flex:1"><div class="appt-name">${p.name}</div><div class="appt-doc">${p.ward}</div></div>${badge(p.status)}</div>`).join("");return`<div class="stat-grid"><div class="stat-card" style="--card-accent:#22c47a"><div class="stat-label">Patients</div><div class="stat-value" style="color:#22c47a">${patients.length}</div><div class="stat-sub">${admitted} admitted</div></div><div class="stat-card" style="--card-accent:#e85050"><div class="stat-label">Critical</div><div class="stat-value" style="color:#e85050">${critical}</div><div class="stat-sub">Urgent care</div></div><div class="stat-card" style="--card-accent:#3d9be8"><div class="stat-label">Doctors</div><div class="stat-value" style=