" onclick="saveBill('${r.id}',${isNew})">Save</button></div>`)}window.saveBill=(id,isNew)=>{const amount=parseFloat(v("f-amount"))||0,paid=parseFloat(v("f-paid"))||0,status=paid>=amount?"Paid":paid>0?"Partial":"Pending",rec={id,patient:v("f-patient"),type:v("f-type"),date:v("f-date"),amount,paid,status};if(isNew)billing.push(rec);else billing=billing.map(b=>b.id===id?rec:b);closeSheet();renderPage()};renderPage();</script></body></html>"""
