echo "=== Generating icons ==="
python3 << 'PYEOF'
import struct,zlib
def make_png(size):
  img=[]
  for y in range(size):
    row=[]
    for x in range(size):
      m=size//8;cx=cy=size//2;arm=size//6;thick=size//9
      ir=x>=m and x<size-m and y>=m and y<size-m
      ic=(abs(x-cx)<=thick and abs(y-cy)<=arm)or(abs(y-cy)<=thick and abs(x-cx)<=arm)
      if ir and ic:row.extend([34,196,122,255])
      elif ir:row.extend([8,20,34,255])
      else:row.extend([6,14,23,255])
    img.append(row)
  def ck(n,d):
    c=struct.pack('>I',len(d))+n+d
    return c+struct.pack('>I',zlib.crc32(n+d)&0xffffffff)
  raw=b''.join(b'\x00'+bytes(r) for r in img)
  p=b'\x89PNG\r\n\x1a\n'
  p+=ck(b'IHDR',struct.pack('>IIBBBBB',size,size,8,2,0,0,0))
  p+=ck(b'IDAT',zlib.compress(raw,9))
  p+=ck(b'IEND',b'')
  return p
base='app/src/main/res'
for d,s in [('mdpi',48),('hdpi',72),('xhdpi',96),('xxhdpi',144),('xxxhdpi',192)]:
  png=make_png(s)
  for n in ['ic_launcher','ic_launcher_round']:
    with open(f'{base}/mipmap-{d}/{n}.png','wb') as f:f.write(png)
print("Icons OK")
PYEOF

